# qos-wire-decode：CONFIG 复用 link-flow-decode 的端口模式、协商、总字节
# 缓存（queue_bytes）、流控（flow_control）、老化与最大帧，顶层再加 qos
# （map/cap/mode/weights/drop，形状同 qos-decode）。事件仅接受原始帧、
# link、advance（service 一律非法）。帧合法性、VLAN 归属与转发判定沿用
# link-flow-decode；各出口副本按最终 802.1Q priority 经 map 入四个优先级
# 队列，同时受本队列字节限额（tail：cap；weighted：ceil(cap*w_i/sum w)）
# 与端口总字节限额 queue_bytes 约束，拒绝只影响该出口。发送器空闲（或
# advance 结算出现空闲点）时按 sp（最高非空队列）或 wrr（续用 qos-decode
# 权重轮次与队列顺序、跳过空队列）选取下一副本；发送不可抢占，时长按
# 协商速率、帧长与 20 字节线缆开销向上取整。链路降级、半双工冲突及
# PAUSE 对在发帧与等待队列的影响沿用 link-flow-decode；同一时刻先结算
# 到期项，末事件后不自动排空。
# ---------------------------------------------------------------------------

QOS_WIRE_CONFIG_KEYS = LINK_WIRE_CONFIG_KEYS | frozenset(("qos",))


def validate_qos_wire_config(config):
    """qos-wire-decode 配置：link-flow-decode 五键加 qos 子文档。"""
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_WIRE_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # ports/age/max_frame/delay（含 rates/modes/queue_bytes/flow_control）
    # 全量校验同 link-flow-decode
    fwd_ports, caps, queues, flows, age, max_frame, delay = (
        validate_link_flow_config(
            {key: config[key] for key in LINK_WIRE_CONFIG_KEYS}
        )
    )
    qos_doc = config["qos"]
    if not isinstance(qos_doc, dict) or frozenset(qos_doc) != QOS_KEYS:
        raise InvalidInput("bad qos")
    mapping = qos_doc["map"]
    cap = qos_doc["cap"]
    mode = qos_doc["mode"]
    weights = qos_doc["weights"]
    drop = qos_doc["drop"]
    if (
        not isinstance(mapping, list)
        or len(mapping) != 8
        or not all(_is_int(q) and 0 <= q <= 3 for q in mapping)
    ):
        raise InvalidInput("bad qos map")
    if not _is_int(cap) or cap <= 0:
        raise InvalidInput("bad qos cap")
    if mode not in QOS_SCHED_MODES:
        raise InvalidInput("bad qos mode")
    if (
        not isinstance(weights, list)
        or len(weights) != 4
        or not all(_is_int(w) and w > 0 for w in weights)
    ):
        raise InvalidInput("bad qos weights")
    if drop not in QOS_DROP_MODES:
        raise InvalidInput("bad qos drop")
    qos = {
        "map": list(mapping),
        "cap": cap,
        "mode": mode,
        "weights": list(weights),
        "drop": drop,
    }
    return fwd_ports, caps, queues, flows, qos, age, max_frame, delay


def validate_qos_wire_events(events, fwd_ports):
    """qos-wire-decode 事件：link/advance/{t,port,data}，service 非法。

    全量校验口径同 link-flow-decode（PAUSE 合法性是运行期结果而非输入
    错误），仅在事件形状层面拒绝 service 及其余未知形状。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys not in (
            FRAME_DECODE_FRAME_KEYS,
            LINK_WIRE_LINK_EVENT_KEYS,
            LINK_WIRE_ADVANCE_EVENT_KEYS,
        ):  # service 等其他形状一律非法输入
            raise InvalidInput("bad event")
    return validate_link_flow_decode_events(events, fwd_ports)


def _qos_wire_priority(raw):
    """单层 802.1Q 标签帧取 TCI 高 3 位优先级；未标记帧优先级为 0。"""
    if raw[12:14] == FRAME_DECODE_TAG:
        return ((raw[14] << 8) | raw[15]) >> 13
    return 0


def _decode_qos_wire_events(events):
    """校验后的 qos-wire 事件对：link/advance 原样；frame 附解码九元组。

    口径同 _decode_link_flow_events（frame-decode 解码，alignment 恒真）；
    工作量预演与正式仿真共用同一纯函数转换。
    """
    raw_frames = [
        (item[1], item[2], item[3]) for item in events if item[0] == "frame"
    ]
    decoded_frames = _decode_raw_frames(raw_frames)
    decoded = []
    frame_index = 0
    for item in events:
        if item[0] == "frame":
            decoded.append(
                ("frame", item[1], item[2], item[3],
                 decoded_frames[frame_index])
            )
            frame_index += 1
        else:
            decoded.append(item)
    return decoded


def qos_wire(
    fwd_ports, caps, queues, flows, qos, age, max_frame, delay, events,
    work_limit=None, observer=None,
):
    """qos-wire-decode 仿真：四优先级队列在线速链路上确定性发送。

    在 link-flow-decode 线速/协商/半双工/PAUSE 模型上，把每口单一等待
    序列改为四个优先级 FIFO（帧与字节双计，含正在发送的队头副本），受
    端口总字节限额与每队列字节限额约束；发送器空闲（含 advance 结算产生
    的空闲点）时按 sp（最高非空队列）或 wrr（续用 qos-decode 权重轮次与
    队列顺序、跳过空队列）选取下一副本。发送非抢占，链路降级/冲突/PAUSE
    语义沿用 link-flow-decode。work_limit 非 None 时按计费点累计 W（初值
    P），首次超过即抛 QosWireWorkLimit；预演与正式仿真共用本函数。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    # 每队列字节限额：tail 即四队列共用 cap；weighted 按权重上取整
    queue_limits = [-(-(cap * w) // weight_total) for w in weights]
    committed = {name: ("down",) for name in by_name}
    pending = {}  # name -> (rate, mode, deadline)
    fdb = {}  # (vlan, mac) -> [port, seen]
    # 每口四队列等待副本（未开始）；head 为正在发送副本（None 发送器空闲）
    waitq = {
        name: [deque(), deque(), deque(), deque()] for name in by_name
    }
    head = {name: None for name in by_name}
    # 各队列剩余帧/字节（等待副本与队头副本均计入，离开端口时核减）
    qframes = {name: [0, 0, 0, 0] for name in by_name}
    qbytes = {name: [0, 0, 0, 0] for name in by_name}
    txq = {name: [0, 0, 0, 0] for name in by_name}
    dropq = {name: [0, 0, 0, 0] for name in by_name}
    occupied = {name: 0 for name in by_name}  # 四队列字节总和
    # 每口持久 WRR 状态 (当前队, 剩余配额)，初始服务 3 队，同 qos-decode
    wrr_state = {name: [3, weights[3]] for name in by_name}
    # PAUSE：pause_until 为发送截止时刻（None 未暂停）；hold_began 为队头
    # 完成后因暂停无法开始的等待区间起点；pause_ns 为累计实际暂停时长
    pause_until = {name: None for name in by_name}
    hold_began = {name: None for name in by_name}
    pause_ns = {name: 0 for name in by_name}
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "quota_full_frames": 0,
            "quota_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
            "pause_frames": 0,
            "pause_unsupported_frames": 0,
            "pause_duration_ns": 0,
        }
        for name in by_name
    }
    results = []
    if observer is not None:
        observer["items"] = []
    work = len(fwd_ports)  # W 初值 P
    if work_limit is not None and work > work_limit:
        raise QosWireWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise QosWireWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

