def _build_log_doc(config, events, items):
    """构造 LOG 文档（含 sha256）；records 与事件等长、同序。"""
    if len(events) != len(items):
        raise InvalidInput("bad log")
    mode = _log_mode(config, events)
    records = []
    # version 初值 0，取事件后值；fdb 模式含 port、seen 的表项实际改变
    # （applied）才加 1（同时刻同口幂等重复学习不计），安全模式每次
    # reload/rollback（无变化亦算）加 1，stp/环路模式链路 up 实际改变
    # （applied）才加 1，链路协商
    # 模式仅 applied 链路项加 1（帧项恒 applied 但不计），链路状态模式
    # 仅 applied 项加 1，qos/lag/mirror/acl/security-check/qos-check/
    # qos-decode/acl-check/mirror-check/lag-check/storm-check 模式仅
    # applied 链路/成员项加 1（帧与 service 恒 applied 但不计），forward-stp/stp-decode/
    # stp-check/forward-stp-storm 模式仅 applied 链路项加 1（帧项恒
    # applied 但不计），forward-static 模式帧恒 applied 且 version 恒 0
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if mode in ("fdb", "stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode in (
            "link_forward", "link_wire", "link_wire_decode",
            "link_flow_decode", "forward_stp",
            "stp_decode", "stp_check", "forward_stp_storm"
        ):
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode in (
            "qos", "lag", "mirror", "acl", "security_check", "qos_check",
            "qos_decode",
            "acl_check", "mirror_check", "lag_check", "storm_check"
        ):
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


