BCAST = "ff:ff:ff:ff:ff:ff"
MAC1 = "00:00:00:00:00:01"
MAC2 = "00:00:00:00:00:02"
PAUSE_DST = "01:80:c2:00:00:01"


def port(name, pvid=1, mode="trunk", rates=None, modes=None,
         queue_bytes=1000000, flow_control=True, pfc=(3,)):
